type Prefs = { offline: boolean; theme: "dark" | "light" | "system"; autosave: boolean; autosaveDelay: number; fontSize: number; confirmOverwrite: boolean; telemetry: boolean; confirmRestore: boolean; defaultFormat: string; printPaper: "A4" | "Letter"; printOrientation: "portrait" | "landscape"; printMargins: number; csvDelimiter: "," | ";" | "\t"; spellCheck: boolean; spellLanguage: "en" | "ur"; density: "comfortable" | "compact" };
const pages: Page[] = ["Home", "Writer", "Sheets", "Slides", "PDF Studio", "AI Agent", "Models & Runtimes", "Devices & Printing", "Data & Backup", "Settings"];
